function normalizeClawHubSha256Integrity(e){const t=e.trim();if(!t)return null;const n=/^sha256-([A-Za-z0-9+/]+={0,1})$/.exec(t);if(n?.[1]){try{const e=Buffer.from(n[1],`base64`);if(e.length===32)return`sha256-${e.toString(`base64`)}`}catch{return null}return null}const r=/^(?:sha256:)?([A-Fa-f0-9]{64})$/.exec(t)?.[1];return r?`sha256-${Buffer.from(r,`hex`).toString(`base64`)}`:null}function normalizeClawHubSha256Hex(e){const t=e.trim();if(!/^[A-Fa-f0-9]{64}$/.test(t))return null;return t.toLowerCase()}export{normalizeClawHubSha256Integrity as n,normalizeClawHubSha256Hex as t};